import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';
const CONTRACT='pls_v16/BINDING_CONTRACT.json',CONTRACT_SHA='6e8558b4545c1084b3a8342eb2f66611de97dc2e78db46f60919666313164140',META_SHA='25d1032044996d2eed8cab3b2c9d6bfbfab91349f0ac6e49ef168c307654b24f',MASK_SHA='8935332736286b4b8238966e7a12ee2049d5fab0816a666061db7cb2c9ee56b0';
const COUNT=Number(process.env.PLS_V16_SHARD_COUNT||8),IN=process.env.PLS_V16_SHARD_DIR||'wip-pls-v16-vector-shards',OUT=process.env.PLS_V16_MERGED_OUT||'wip-pls-v16-vector-sharded';
const sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex'),ok=(c,m)=>{if(!c)throw new Error(m);};ok(sha(CONTRACT)===CONTRACT_SHA,'CONTRACT_SHA');const C=JSON.parse(fs.readFileSync(CONTRACT,'utf8'));fs.mkdirSync(OUT,{recursive:true});
const reports=[];for(let i=0;i<COUNT;i++){const tag=i+'-of-'+COUNT,p=path.join(IN,'shard-'+tag+'.json');ok(fs.existsSync(p),'SHARD_REPORT_MISSING '+i);const r=JSON.parse(fs.readFileSync(p,'utf8'));ok(r.shard_index===i&&r.shard_count===COUNT,'SHARD_ID '+i);ok(r.binding_contract_sha256===CONTRACT_SHA&&r.metadata_sha256===META_SHA&&r.jesus_mask_sha256===MASK_SHA&&r.model_sha256===C.model.model_sha256,'SHARD_BINDING '+i);ok(r.backend==='BROWSER_WASM_PINNED_SINGLETON'&&r.repeat_determinism===true,'SHARD_RUNTIME '+i);reports.push(r);}
let cursor=0,totalRows=0;const vecs=[],norms=[];for(const r of reports){ok(r.start_row===cursor,'SHARD_GAP '+r.shard_index);cursor=r.end_row_exclusive;totalRows+=r.row_count;const tag=r.shard_index+'-of-'+COUNT,vp=path.join(IN,'vectors.part-'+tag+'.i8'),np=path.join(IN,'inverse_norms.part-'+tag+'.f32le');ok(fs.existsSync(vp)&&fs.existsSync(np),'SHARD_BYTES_MISSING '+r.shard_index);ok(fs.statSync(vp).size===r.row_count*C.model.embedding_dim&&fs.statSync(np).size===r.row_count*4,'SHARD_GEOMETRY '+r.shard_index);ok(sha(vp)===r.vectors.sha256&&sha(np)===r.inverse_norms.sha256,'SHARD_HASH '+r.shard_index);vecs.push(fs.readFileSync(vp));norms.push(fs.readFileSync(np));}
ok(cursor===C.chunker.expected_passages&&totalRows===C.chunker.expected_passages,'TOTAL_ROWS');const vectors=Buffer.concat(vecs),inverse=Buffer.concat(norms);ok(vectors.length===C.chunker.expected_passages*C.model.embedding_dim,'VECTOR_TOTAL_BYTES');ok(inverse.length===C.chunker.expected_passages*4,'NORM_TOTAL_BYTES');const vp=path.join(OUT,'vectors.i8'),np=path.join(OUT,'inverse_norms.f32le');fs.writeFileSync(vp,vectors);fs.writeFileSync(np,inverse);
const report={schema:'ldc-pls-v16-vector-sharded-build-v1',status:'ENGINEERING_ONLY__NOT_QUALIFIED__NOT_DEPLOYABLE',binding_contract_sha256:CONTRACT_SHA,pack_id:C.pack_id,backend:'BROWSER_WASM_PINNED_SINGLETON_SHARDED',shard_count:COUNT,rows:totalRows,cols:C.model.embedding_dim,metadata_sha256:META_SHA,jesus_mask_sha256:MASK_SHA,vectors:{bytes:vectors.length,sha256:sha(vp)},inverse_norms:{bytes:inverse.length,sha256:sha(np)},shards:reports.map(r=>({index:r.shard_index,start:r.start_row,end:r.end_row_exclusive,vector_sha256:r.vectors.sha256,norm_sha256:r.inverse_norms.sha256})),app_runtime_wired:false,deployment_authorized:false};fs.writeFileSync(path.join(OUT,'vector_build_report.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));
